using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using System.Data;
using Core;
using DataAccess;
using BO;
using System.Configuration;

namespace InformationWeb.Controls.Sims
{
    public partial class UTeacher5 : System.Web.UI.UserControl
    {

        public string PermissionID
        {
            set { ViewState["PermissionID" + this.ClientID] = value; }
            get
            {
                if (ViewState["PermissionID" + this.ClientID] != null)
                    return ViewState["PermissionID" + this.ClientID].ToString();
                return null;
            }
        }

        public string TeacherName
        {
            get
            {
                if (ddlTeacherID.SelectedIndex > 0)
                    return ddlTeacherID.SelectedItem.Text;
                else
                    return "";
            }
        }


        public string TeacherID
        {
            get
            {
                if (ddlTeacherID.SelectedIndex > 0)
                    return ddlTeacherID.SelectedItem.Value;
                else
                    return "";
            }
            set
            {
                if (value != null && value != "")
                {
                    if (ddlTeacherID.DataSource == null)
                    {
                        LoadData();
                    }
                }

                ddlTeacherID.SelectedValue = WebGlobal.ValueForDropBoxList(value);
            }
        }

        public string ScienceID
        {
            get
            {
                if (ddlScienceID.SelectedIndex > 0)
                    return ddlScienceID.SelectedValue;
                else
                    return "";
            }
        }

        public string SubjectGroupID
        {
            get
            {
                if (ddlSubjectGroupID.SelectedIndex > 0)
                    return ddlSubjectGroupID.SelectedValue;
                else
                    return "";
            }
        }

        private string SubjectGroupSessionKey
        {
            get { return "UTeacher5_SUBJECTGROUP_TABLE_" + this.ClientID; }
        }

        private string TeacherSessionKey
        {
            get { return "UTeacher5_TEACHER_TABLE_" + this.ClientID; }
        }

        private bool IsPermissionFilterEnabled()
        {
            return this.PermissionID != null && this.PermissionID.Trim() != "";
        }

        private bool HasSciencePermission(string scienceID)
        {
            if (!IsPermissionFilterEnabled())
                return true;

            if (WebGlobal.HasPermission(this.PermissionID, scienceID, null))
                return true;

            DataTable dtbSubjectGroup = new SIM_SubjectGroupDAO().Search();
            if (dtbSubjectGroup != null)
            {
                foreach (DataRow drw in dtbSubjectGroup.Rows)
                {
                    if (drw["ScienceID"].ToString() != scienceID)
                        continue;

                    if (WebGlobal.HasPermission(this.PermissionID, scienceID, drw[SIM_SubjectGroup.C_SUBJECTGROUPID].ToString()))
                        return true;
                }
            }

            return false;
        }

        private bool HasSubjectGroupPermission(string scienceID, string subjectGroupID)
        {
            if (!IsPermissionFilterEnabled())
                return true;

            if (WebGlobal.HasPermission(this.PermissionID, scienceID, null))
                return true;

            return WebGlobal.HasPermission(this.PermissionID, scienceID, subjectGroupID);
        }

        private void FilterScienceByPermission(DataTable dtbScience)
        {
            if (!IsPermissionFilterEnabled() || dtbScience == null)
                return;

            for (int i = dtbScience.Rows.Count - 1; i >= 0; i--)
            {
                string strScienceID = dtbScience.Rows[i][SIM_Science.C_SCIENCEID].ToString();
                if (!HasSciencePermission(strScienceID))
                    dtbScience.Rows.RemoveAt(i);
            }
        }

        private void FilterSubjectGroupByPermission(DataTable dtbSubjectGroup, string scienceID)
        {
            if (!IsPermissionFilterEnabled() || dtbSubjectGroup == null)
                return;

            for (int i = dtbSubjectGroup.Rows.Count - 1; i >= 0; i--)
            {
                DataRow drw = dtbSubjectGroup.Rows[i];
                string strScienceID = drw["ScienceID"].ToString();
                string strSubjectGroupID = drw[SIM_SubjectGroup.C_SUBJECTGROUPID].ToString();

                if (scienceID != null && scienceID != "" && strScienceID != scienceID)
                    continue;

                if (!HasSubjectGroupPermission(strScienceID, strSubjectGroupID))
                    dtbSubjectGroup.Rows.RemoveAt(i);
            }
        }

        public void LoadData()
        {
            DataTable dtbScience = new SIM_ScienceDAO().Search();
            FilterScienceByPermission(dtbScience);
            WebGlobal.InitDropDownList(ddlScienceID, dtbScience, SIM_Science.C_SCIENCEID, SIM_Science.C_SCIENCENAME, "--Chọn--");


            DataTable dtbSubjectGroup = new SIM_SubjectGroupDAO().Search();
            FilterSubjectGroupByPermission(dtbSubjectGroup, null);
            Session[SubjectGroupSessionKey] = dtbSubjectGroup;
            WebGlobal.InitDropDownList(ddlSubjectGroupID, dtbSubjectGroup, SIM_SubjectGroup.C_SUBJECTGROUPID, SIM_SubjectGroup.C_SUBJECTGROUPNAME, "--Chọn--");

            string strCondition = null;
            if (ddlScienceID.SelectedIndex > 0)
                strCondition = " And ScienceID = '" + ddlScienceID.SelectedValue + "'";
            if (ddlSubjectGroupID.SelectedIndex > 0)
                strCondition += " And SubjectGroupID = '" + ddlSubjectGroupID.SelectedValue + "'";
            if (strCondition != null)
                strCondition = strCondition.Substring(5);


            DataTable dtbTeacher = new SIM_TeacherDAO().Search();
            if (dtbTeacher != null)
            {
                foreach (DataRow drw in dtbTeacher.Rows)
                    drw["TeacherID"] = drw["TeacherID"].ToString().ToLower();

                Session[TeacherSessionKey] = dtbTeacher;
                WebGlobal.InitDropDownList(ddlTeacherID, dtbTeacher, SIM_Teacher.C_TEACHERID, "FullName", "--Chọn--", strCondition);
            }
            else
                MsgBox.Show(this, "Việc tải thông tin giảng viên bị lỗi!");

        }

        private void FilterSubjectGroup()
        {
            string strCondition = null;
            if (ddlScienceID.SelectedIndex > 0)
                strCondition = " And ScienceID = '" + ddlScienceID.SelectedValue + "'";
            if (strCondition != null)
                strCondition = strCondition.Substring(5);

            DataTable dtbSubjectGroup;
            if (Session[SubjectGroupSessionKey] != null)
                dtbSubjectGroup = (Session[SubjectGroupSessionKey] as DataTable).Copy();
            else
            {
                dtbSubjectGroup = new SIM_SubjectGroupDAO().Search();
                FilterSubjectGroupByPermission(dtbSubjectGroup, null);
            }

            if (ddlScienceID.SelectedIndex > 0)
                FilterSubjectGroupByPermission(dtbSubjectGroup, ddlScienceID.SelectedValue);

            WebGlobal.InitDropDownList(ddlSubjectGroupID, dtbSubjectGroup, SIM_SubjectGroup.C_SUBJECTGROUPID, SIM_SubjectGroup.C_SUBJECTGROUPNAME, "--Chọn--", strCondition);

        }

        private void FilterTeacher()
        {
            string strCondition = null;
            if (ddlScienceID.SelectedIndex > 0)
                strCondition = " And ScienceID = '" + ddlScienceID.SelectedValue + "'";
            if (ddlSubjectGroupID.SelectedIndex > 0)
                strCondition += " And SubjectGroupID = '" + ddlSubjectGroupID.SelectedValue + "'";
            if (strCondition != null)
                strCondition = strCondition.Substring(5);

            DataTable dtbTeacher;
            if (Session[TeacherSessionKey] != null)
                dtbTeacher = Session[TeacherSessionKey] as DataTable;
            else
                dtbTeacher = new SIM_TeacherDAO().Search();

            WebGlobal.InitDropDownList(ddlTeacherID, dtbTeacher, SIM_Teacher.C_TEACHERID, "FullName", "--Chọn--", strCondition);

        }

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                if (ddlTeacherID.DataSource == null)
                    LoadData();
            }
        }

        protected void ddlScienceID_SelectedIndexChanged(object sender, EventArgs e)
        {
            FilterSubjectGroup();
            FilterTeacher();
        }

        protected void ddlSubjectGroupID_SelectedIndexChanged(object sender, EventArgs e)
        {
            FilterTeacher();
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            if (SearchClick != null)
                SearchClick(ddlScienceID.SelectedValue == "" ? null : ddlScienceID.SelectedValue,
                            ddlSubjectGroupID.SelectedValue == "" ? null : ddlSubjectGroupID.SelectedValue,
                            ddlTeacherID.SelectedValue == "" ? null : ddlTeacherID.SelectedValue);
        }

        #region Event Handler

        public delegate void SearchDelegate(object scienceID, object subjectGroupID, object teacherID);
        public event SearchDelegate SearchClick = null;

        #endregion


    }
}

