private bool ValidateScienceRequired(object scienceID)
{
    if (NormalizeFilterValue(scienceID) == null)
    {
        MsgBox.ShowWarning("Bạn phải chọn khoa trước khi tải danh sách!");
        ClearList();
        return false;
    }
    return true;
}

private bool ValidateFilterPermission(object scienceID, object subjectGroupID)
{
    object objScienceID = NormalizeFilterValue(scienceID);
    object objSubjectGroupID = NormalizeFilterValue(subjectGroupID);

    if (objScienceID == null)
        return true;

    string strScienceID = objScienceID.ToString();
    string strSubjectGroupID = objSubjectGroupID != null ? objSubjectGroupID.ToString() : null;

    if (WebGlobal.HasPermission(PERMISSION_VIEW, strScienceID, null))
        return true;

    if (strSubjectGroupID != null && WebGlobal.HasPermission(PERMISSION_VIEW, strScienceID, strSubjectGroupID))
        return true;

    if (strSubjectGroupID == null)
    {
        SIM_SubjectGroup objSubjectGroup = new SIM_SubjectGroup();
        DataTable dtbSubjectGroup = objSubjectGroup.Search("@ScienceID", strScienceID);
        if (dtbSubjectGroup != null)
        {
            foreach (DataRow drw in dtbSubjectGroup.Rows)
            {
                if (WebGlobal.HasPermission(PERMISSION_VIEW, strScienceID, drw["SubjectGroupID"].ToString()))
                    return true;
            }
        }
    }

    MsgBox.ShowWarning("Bạn không có quyền trên khoa/bộ môn này!");
    ClearList();
    return false;
}

