using System;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using System.Data;
using System.Collections;
using DataAccess;
using BO;

namespace InformationWeb.Controls.Sims
{
    public partial class UTeacher5 : System.Web.UI.UserControl
    {
        private Hashtable _hstScience = null;
        private Hashtable _hstFullScience = null;
        private Hashtable _hstSubjectGroup = null;

        public string PermissionID
        {
            set { ViewState["PermissionID" + ClientID] = value; }
            get { return ViewState["PermissionID" + ClientID] as string; }
        }

        public string TeacherName
        {
            get { return ddlTeacherID.SelectedIndex > 0 ? ddlTeacherID.SelectedItem.Text : ""; }
        }

        public string TeacherID
        {
            get { return ddlTeacherID.SelectedIndex > 0 ? ddlTeacherID.SelectedItem.Value : ""; }
            set
            {
                if (value != null && value != "" && ddlTeacherID.Items.Count <= 1)
                    LoadData();
                ddlTeacherID.SelectedValue = WebGlobal.ValueForDropBoxList(value);
            }
        }

        public string ScienceID
        {
            get { return ddlScienceID.SelectedIndex > 0 ? ddlScienceID.SelectedValue : ""; }
        }

        public string SubjectGroupID
        {
            get { return ddlSubjectGroupID.SelectedIndex > 0 ? ddlSubjectGroupID.SelectedValue : ""; }
        }

        private string SessionKey(string name)
        {
            return "UTeacher5_" + name + "_" + ClientID;
        }

        private bool UsePermissionFilter()
        {
            if (PermissionID == null || PermissionID.Trim() == "")
                return false;
            DCore.SessionUser objUser = WebGlobal.User;
            return objUser == null || objUser.UserName.ToLower() != "administrator";
        }

        private DataTable LoadPermissionScope()
        {
            if (!UsePermissionFilter())
                return null;

            DCore.SessionUser objUser = WebGlobal.User;
            if (objUser == null)
                return null;

            string strKey = SessionKey("SCOPE_" + PermissionID + "_" + objUser.UserName);
            if (Session[strKey] != null)
                return Session[strKey] as DataTable;

            DataTable dtbScope = new SystemObject.SYS_User().GetDataTable(
                "SYS_User_SearchPermission_ScienceAndSubjectGroup",
                "@Username", objUser.UserName,
                "@PermissionID", PermissionID);

            Session[strKey] = dtbScope;
            return dtbScope;
        }

        private void EnsurePermissionLookup()
        {
            if (_hstScience != null || !UsePermissionFilter())
                return;

            _hstScience = new Hashtable();
            _hstFullScience = new Hashtable();
            _hstSubjectGroup = new Hashtable();

            DataTable dtbScope = LoadPermissionScope();
            if (dtbScope == null)
                return;

            foreach (DataRow drw in dtbScope.Rows)
            {
                string strScienceID = drw["ScienceID"].ToString();
                _hstScience[strScienceID] = true;

                string strSubjectGroupID = drw["SubjectGroupID"] == DBNull.Value ? "" : drw["SubjectGroupID"].ToString();
                if (strSubjectGroupID == "" || strSubjectGroupID == "0")
                    _hstFullScience[strScienceID] = true;
                else
                    _hstSubjectGroup[strScienceID + "|" + strSubjectGroupID] = true;
            }
        }

        private bool CanAccessScience(string scienceID)
        {
            if (!UsePermissionFilter())
                return true;
            EnsurePermissionLookup();
            return _hstScience != null && _hstScience.Contains(scienceID);
        }

        private bool CanAccessSubjectGroup(string scienceID, string subjectGroupID)
        {
            if (!UsePermissionFilter())
                return true;
            EnsurePermissionLookup();
            if (_hstScience == null)
                return false;
            if (_hstFullScience.Contains(scienceID))
                return true;
            return _hstSubjectGroup.Contains(scienceID + "|" + subjectGroupID);
        }

        public bool ValidateFilterPermission(object scienceID, object subjectGroupID)
        {
            if (!UsePermissionFilter())
                return true;
            if (scienceID == null || scienceID.ToString().Trim() == "")
                return true;

            string strScienceID = scienceID.ToString();
            if (!CanAccessScience(strScienceID))
                return false;
            if (subjectGroupID == null || subjectGroupID.ToString().Trim() == "")
                return true;

            return CanAccessSubjectGroup(strScienceID, subjectGroupID.ToString());
        }

        private void FilterByPermission(DataTable dtb, string scienceField, string subjectGroupField)
        {
            if (!UsePermissionFilter() || dtb == null)
                return;

            for (int i = dtb.Rows.Count - 1; i >= 0; i--)
            {
                DataRow drw = dtb.Rows[i];
                string strScienceID = drw[scienceField].ToString();
                if (!CanAccessScience(strScienceID))
                {
                    dtb.Rows.RemoveAt(i);
                    continue;
                }
                if (subjectGroupField != null && !CanAccessSubjectGroup(strScienceID, drw[subjectGroupField].ToString()))
                    dtb.Rows.RemoveAt(i);
            }
        }

        private string BuildFilterCondition(bool includeSubjectGroup)
        {
            string strCondition = "";
            if (ddlScienceID.SelectedIndex > 0)
                strCondition = "ScienceID = '" + ddlScienceID.SelectedValue + "'";
            if (includeSubjectGroup && ddlSubjectGroupID.SelectedIndex > 0)
                strCondition += (strCondition == "" ? "" : " And ") + "SubjectGroupID = '" + ddlSubjectGroupID.SelectedValue + "'";
            return strCondition;
        }

        private void BindDropDown(DropDownList ddl, DataTable dtb, string valueField, string textField, string filter)
        {
            WebGlobal.InitDropDownList(ddl, dtb, valueField, textField, "--Chọn--", filter == "" ? null : filter);
        }

        public void LoadData()
        {
            _hstScience = null;
            _hstFullScience = null;
            _hstSubjectGroup = null;
            Session.Remove(SessionKey("SUBJECTGROUP"));
            Session.Remove(SessionKey("TEACHER"));

            string strScopePrefix = SessionKey("SCOPE_" + PermissionID);
            foreach (string strKey in Session.Keys)
            {
                if (strKey != null && strKey.StartsWith(strScopePrefix))
                    Session.Remove(strKey);
            }

            LoadPermissionScope();

            DataTable dtbScience = new SIM_ScienceDAO().Search();
            FilterByPermission(dtbScience, SIM_Science.C_SCIENCEID, null);
            BindDropDown(ddlScienceID, dtbScience, SIM_Science.C_SCIENCEID, SIM_Science.C_SCIENCENAME, "");

            DataTable dtbSubjectGroup = new SIM_SubjectGroupDAO().Search();
            FilterByPermission(dtbSubjectGroup, "ScienceID", SIM_SubjectGroup.C_SUBJECTGROUPID);
            Session[SessionKey("SUBJECTGROUP")] = dtbSubjectGroup;
            BindDropDown(ddlSubjectGroupID, dtbSubjectGroup, SIM_SubjectGroup.C_SUBJECTGROUPID, SIM_SubjectGroup.C_SUBJECTGROUPNAME, BuildFilterCondition(false));

            DataTable dtbTeacher = new SIM_TeacherDAO().Search();
            if (dtbTeacher == null)
            {
                MsgBox.Show(this, "Việc tải thông tin giảng viên bị lỗi!");
                return;
            }

            foreach (DataRow drw in dtbTeacher.Rows)
                drw["TeacherID"] = drw["TeacherID"].ToString().ToLower();

            Session[SessionKey("TEACHER")] = dtbTeacher;
            BindDropDown(ddlTeacherID, dtbTeacher, SIM_Teacher.C_TEACHERID, "FullName", BuildFilterCondition(true));
        }

        private void FilterSubjectGroup()
        {
            DataTable dtb = Session[SessionKey("SUBJECTGROUP")] as DataTable;
            if (dtb == null)
                dtb = new SIM_SubjectGroupDAO().Search();
            BindDropDown(ddlSubjectGroupID, dtb, SIM_SubjectGroup.C_SUBJECTGROUPID, SIM_SubjectGroup.C_SUBJECTGROUPNAME, BuildFilterCondition(false));
        }

        private void FilterTeacher()
        {
            DataTable dtb = Session[SessionKey("TEACHER")] as DataTable;
            if (dtb == null)
                dtb = new SIM_TeacherDAO().Search();
            BindDropDown(ddlTeacherID, dtb, SIM_Teacher.C_TEACHERID, "FullName", BuildFilterCondition(true));
        }

        protected void ddlScienceID_SelectedIndexChanged(object sender, EventArgs e)
        {
            FilterSubjectGroup();
            FilterTeacher();
        }

        protected void ddlSubjectGroupID_SelectedIndexChanged(object sender, EventArgs e)
        {
            FilterTeacher();
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            if (SearchClick != null)
                SearchClick(
                    ScienceID == "" ? null : (object)ScienceID,
                    SubjectGroupID == "" ? null : (object)SubjectGroupID,
                    TeacherID == "" ? null : (object)TeacherID);
        }

        public delegate void SearchDelegate(object scienceID, object subjectGroupID, object teacherID);
        public event SearchDelegate SearchClick = null;
    }
}

